code.en:
# forward chaining fires rules until no new facts appear
facts = {"A"}
rules = [(("A",), "B"), (("B",), "C")]
changed = True
while changed:
    changed = False
    for cond, res in rules:
        if all(c in facts for c in cond) and res not in facts:
            facts.add(res); changed = True
print(sorted(facts))

