exercises.solution:
def prove(goal, facts, rules):
    def holds(g, active):
        if g in facts:
            return True
        if g in active:
            return False
        return any(all(holds(p, active | {g}) for p in premises)
                   for premises, conclusion in rules if conclusion == g)
    return holds(goal, frozenset())

